def _clean_dialed_number(raw: str) -> str:
    """
    Strip human formatting from a dialed number and normalize its prefix.

    Returns a string that is either bare digits or ``+`` followed by digits.
    The ``00`` international access prefix (common outside the NANP, e.g.
    ``0044 20 7183 8750``) is treated as equivalent to a leading ``+``.
    """
    value = (raw or "").strip()
    if not value:
        return ""

    cleaned = _NON_DIGIT_RE.sub("", value.replace(" ", ""))
    if not cleaned:
        return ""

    if cleaned.startswith("+"):
        return "+" + cleaned[1:].lstrip("+")

    if cleaned.startswith("00") and len(cleaned) > 2:
        # 00 is the international access code; the country code follows it.
        return "+" + cleaned[2:].lstrip("0")

    return cleaned


def _format_parsed_number(parsed: phonenumbers.PhoneNumber, *, require_valid: bool) -> Optional[str]:

Accepts international numbers with or without a + prefix (a leading 00
international access code is also accepted). Tries the configured default
region first, then common regions, preferring valid parses over
possible-only parses. Falls back to a +digits form for 8–15 digit inputs.
"""
cleaned = _clean_dialed_number(raw)
if not cleaned:
    return None

if cleaned.startswith("+"):
    for require_valid in (True, False):
        formatted = _try_parse_candidate(cleaned, None, require_valid=require_valid)
        if formatted:
            return formatted

digits = cleaned.lstrip("+")
if not digits:
    return None

regions: list[str] = []
default = (default_region or _FALLBACK_REGION).strip().upper()
if default:
    regions.append(default)
for region in _CRM_FALLBACK_REGIONS:
    if region not in regions:
        regions.append(region)

valid_matches: list[str] = []
possible_matches: list[str] = []
for region in regions:
    formatted = _try_parse_candidate(digits, region, require_valid=True)
    if formatted:
        valid_matches.append(formatted)
        continue
    formatted = _try_parse_candidate(digits, region, require_valid=False)
    if formatted:
        possible_matches.append(formatted)

# Regions are ordered with the contact's configured region first, so the
# first match wins when the digits could belong to more than one country.
if valid_matches:
    return valid_matches[0]
if possible_matches:
    return possible_matches[0]

