def _normalize_key(value: str) -> str:
    return re.sub(r"\s+", " ", re.sub(r"[_\-]+", " ", value.strip().lower())).strip()


def _compact_key(value: str) -> str:
    return re.sub(r"[\s_\-]+", "", value.strip().lower())


# Compacted canonical id (e.g. "workingcapital") → canonical id.
_COMPACT_LOAN_TYPE_IDS: dict[str, str] = {
    _compact_key(c["id"]): c["id"] for c in LOAN_TYPE_CHOICES
}


def _titleize(value: str) -> str:
    """Word-by-word capitalization that leaves the rest of each word alone."""
    words = [w for w in _normalize_key(value).split(" ") if w]
    return " ".join(w[:1].upper() + w[1:] for w in words)


def loan_type_label(loan_type_id: Optional[str]) -> str:
    if not loan_type_id:
        return ""
    for choice in LOAN_TYPE_CHOICES:
        if choice["id"] == loan_type_id:
            return choice["label"]
    resolved = resolve_loan_type(loan_type_id)
    if resolved:
        for choice in LOAN_TYPE_CHOICES:
            if choice["id"] == resolved:
                return choice["label"]
    # Unknown / legacy id: render it as a readable, spaced, capitalized label
    # (e.g. "hard_money" → "Hard Money").
    return _titleize(loan_type_id) or loan_type_id


def resolve_loan_type(raw: str) -> Optional[str]:
    """Map a CSV/UI loan type string to a canonical id, or None if unrecognized."""
    value = (raw or "").strip()
    if not value:
        return None
    lowered = value.lower()
    if lowered in _LOAN_TYPE_IDS:
        return lowered
    compact = _compact_key(value)
    if compact in _LOAN_TYPE_IDS:
        return compact
    if compact in _COMPACT_LOAN_TYPE_IDS:
        return _COMPACT_LOAN_TYPE_IDS[compact]
    normalized = _normalize_key(value)
    if normalized in _EXTRA_ALIASES:
        return _EXTRA_ALIASES[normalized]
    for choice in LOAN_TYPE_CHOICES:
        if _normalize_key(choice["label"]) == normalized:
            return choice["id"]
        if _normalize_key(choice["id"]) == normalized:
            return choice["id"]
    for alias, canonical in _EXTRA_ALIASES.items():
        if _compact_key(alias) == compact:
            return canonical
    return None

